import {cpSync,mkdirSync,symlinkSync,readFileSync,writeFileSync} from 'node:fs';
import {resolve,join} from 'node:path';import {createHash} from 'node:crypto';
const frozen='/Users/stephenbelanger/Code/nodejs/tint/.tint-bootstrap/node-toolchain-managed-templates-v1';
const root=resolve('.tint-bootstrap/b-phase2/symbolized-frozen-host');mkdirSync(root);
cpSync(frozen+'/tools',root+'/tools',{recursive:true});cpSync(frozen+'/package.json',root+'/package.json');symlinkSync(frozen+'/node_modules',root+'/node_modules');
const tool=root+'/tools/test262-native.ts', original=readFileSync(tool,'utf8');
const patched=original.replace('const built = buildMacOSProgram({','const built = buildMacOSProgram({\n      debugSymbols: true,\n      debugDirectory: '+JSON.stringify(process.cwd())+',');
if(original===patched)throw Error('instrumentation target missing');writeFileSync(tool,patched);
const {prepareNativeScriptProgram,createNativeBatchBuilder}=await import(tool);
const {executionPlan}=await import(root+'/tools/test262-execution.ts');
const {testMetadata}=await import(root+'/tools/test262.ts');
const {readWorkspaceSourceSnapshot,workspaceSourceIdentity}=await import(root+'/tools/workspace-sources.ts');
const snapshot=readWorkspaceSourceSnapshot(frozen+'/source-snapshot.json'),checkout=frozen+'/../test262';
const selected=[['addition/S11.6.1_A1.js','sloppy'],['division/S11.5.2_A1.js','sloppy'],['division/S11.5.2_A1.js','strict']];
const cases=selected.map(([path,variant])=>{const filename=resolve(checkout,'test/language/expressions',path),source=readFileSync(filename,'utf8'),metadata=testMetadata(source),plan=executionPlan(source,variant,metadata);const harness=plan.harness.map(name=>({filename:resolve(checkout,'harness',name),source:readFileSync(resolve(checkout,'harness',name),'utf8')}));const p=prepareNativeScriptProgram(plan,variant,harness,filename,undefined,true,true);if(!p.ok)throw Error(JSON.stringify(p));return{scripts:p.scripts,asynchronous:plan.asynchronous,canSuspend:plan.canSuspend,...(p.root?{modules:p.root.entries,scriptRoot:{absent:p.root.absent}}:{})};});
writeFileSync(resolve('.tint-bootstrap/b-phase2/diagnostic-inputs.json'),JSON.stringify({selected,sourceSnapshot:workspaceSourceIdentity(snapshot),instrumentation:'Frozen host copied locally; debugSymbols and debugDirectory enabled only. Native source bytes unchanged.',originalHostSha256:createHash('sha256').update(original).digest('hex'),symbolizedHostSha256:createHash('sha256').update(patched).digest('hex')},null,2));
const built=createNativeBatchBuilder(snapshot,true)(cases);if(!built.ok)throw Error(JSON.stringify(built));writeFileSync(resolve('.tint-bootstrap/b-phase2/operator-timeouts-debug'),built.bytes,{mode:0o755,flag:'wx'});console.log('built',built.bytes.length);
